// GitHubに無くなったリポジトリのバックアップ（Drive上のファイル）を削除対象にする
const normalize = (v) =>
  String(v ?? "").trim().replace(/\.zip$/i, "").toLowerCase();

const repoNames = new Set(
  $("全てのレポジトリ取得").all()
    .map((i) => normalize(i.json.name))
    .filter(Boolean),
);

// 安全装置: GitHub側のリポジトリが1件も取れていない場合は
// (トークン失効・API障害などの可能性があるため) 何も削除しない
if (repoNames.size === 0) {
  return [];
}

// Driveのフォルダが空のときは Always Output Data で空のアイテムが来るので、IDのないものは除く
return $input.all()
  .map((i) => i.json)
  .filter((f) => {
    const key = normalize(f.name);
    return f.id && key && !repoNames.has(key);
  })
  .map((f) => ({ json: { name: f.name, id: f.id } }));

// GitHubのリポジトリごとに、Drive上の既存バックアップのファイルIDを紐付ける
const normalize = (v) =>
  String(v ?? "").trim().replace(/\.zip$/i, "").toLowerCase();

// Driveの既存バックアップを「リポジトリ名(小文字) → ファイルID」で索引化
// (Driveのフォルダが空のときは Always Output Data で空のアイテムが来るので、IDのないものは除く)
const driveIdByName = new Map();
for (const { json: f } of $input.all()) {
  const key = normalize(f.name);
  if (f.id && key && !driveIdByName.has(key)) {
    driveIdByName.set(key, f.id);
  }
}

return $("全てのレポジトリ取得").all()
  .map((i) => i.json)
  .filter((r) => r.name && r.owner?.login)
  .map((r) => ({
    json: {
      owner: r.owner.login,
      name: r.name,
      driveFileId: driveIdByName.get(normalize(r.name)) ?? null,
    },
  }));

// 「レポジトリダウンロード」で失敗したリポジトリをまとめて、ワークフローをエラーで止める。
// エラーで止めると「エラー通知」ワークフローが Slack に知らせる（以前はエラー出力がどこにもつながっておらず、黙って抜け落ちていた）。
//
// 注意: このノードはキャンバス上で「レポジトリが存在している」より下に置くこと。
// 実行順序 v1 では上にある分岐から先に動くので、下に置けば成功したリポジトリのアップロードが全部終わってから止まる。
// 上に置くと先にここで止まり、その日は1件もアップロードされない。
const MAX_LINES = 10;

const lines = $input.all().map((item, i) => {
  // エラー出力のアイテムには元の入力（owner / name）と error が入っている。
  // 入っていなければ、ペアになっている「バックアップ対象リスト」の行から取る
  let repo = item.json ?? {};
  if (!repo.name) {
    try {
      repo = $('バックアップ対象リスト').itemMatching(i).json;
    } catch (e) {
      // 対応する行が見つからないときは名前不明のまま報告する
    }
  }
  const err = item.json?.error ?? {};
  const reason = typeof err === 'string'
    ? err
    : (err.message || err.description || JSON.stringify(err));
  const status = typeof err === 'object' ? (err.httpCode ?? err.status ?? err.statusCode ?? '') : '';
  const name = repo.name ? `${repo.owner ? `${repo.owner}/` : ''}${repo.name}` : '(リポジトリ名不明)';
  return `${name}${status ? ` [${status}]` : ''}: ${String(reason).slice(0, 80)}`;
});

if (lines.length === 0) return [];

throw new Error(
  `${lines.length}件のリポジトリをダウンロードできず、バックアップしていません。\n`
  + lines.slice(0, MAX_LINES).map((s) => `・${s}`).join('\n')
  + (lines.length > MAX_LINES ? `\n他 ${lines.length - MAX_LINES}件` : ''),
);
